'use strict';
const input=$input.first()?.json||{};
const clean=(v,n=0)=>{let s=String(v??'').normalize('NFKC');
s=s.replace(/(bot)[0-9]{6,}:[A-Za-z0-9_-]{20,}/gi,'$1[REDACTED]')
 .replace(/(Bearer\s+)[A-Za-z0-9._~+\/-]{16,}/gi,'$1[REDACTED]')
 .replace(/((?:^|[?&\s;,\[{(\"'])?(?:api[_-]?key|token|secret|password|key)\s*[:=]\s*)[^&\s,;\]}\)\"']+/gi,'$1[REDACTED]')
 .replace(/\bsk-[A-Za-z0-9_-]{16,}\b/g,'[REDACTED_OPENAI_KEY]');
return (n?s.slice(0,n):s).trim();};
const execution=input.execution||{};const workflow=input.workflow||{};const trigger=input.trigger||{};
const err=execution.error||input.error||{};const executionId=clean(execution.id||input.executionId,160);
const workflowId=clean(workflow.id||input.workflowId,160);const occurredAt=new Date().toISOString();
