let h=2166136261;for(let i=0;i<raw.length;i++){h^=raw.charCodeAt(i);h=Math.imul(h,16777619);}const hash=(h>>>0).toString(16).padStart(8,'0');
const eventId=`err_${workflowId||'unknown'}_${executionId||hash}`.slice(0,240);
const message=clean(err.message||input.message||'Unknown workflow error',4000);
const retryable=!/(invalid identity|permission|unauthori[sz]ed|forbidden|schema mismatch|unknown fields)/i.test(message);
